import pandas as pd
rows={}
for l in gzip.open('studies/data/raw/paper_2_GSE21618_series_matrix.txt.gz','rt'):
    p=l.rstrip('\n').split('\t')
    if p[0] in('!Sample_title','!Sample_geo_accession') : rows[p[0]]=[x.strip('"') for x in p[1:]]
    if p[0]=='!Sample_characteristics_ch1' and any(x.strip('"').startswith(('treatment','time','tamoxifen phen','cell line')) for x in p[1:3]):
        k=p[1].strip('"').split(':')[0]; rows[k]=[x.strip('"') for x in p[1:]]
df=pd.DataFrame(rows); pd.set_option('display.max_rows',300,'display.width',200)
print(df.drop(columns=['cell line']))

print(df[['!Sample_title','!Sample_source_name_ch1','c8','c9']].to_string())
